import threading
from uuid import uuid4

class Queue:
    def __init__(self):
        self._lock = threading.Lock()
        self.jobs = {}
        self._order = []  # Track insertion order for FIFO selection

    def add(self, job_id):
        with self._lock:
            if job_id not in self.jobs:
                self.jobs[job_id] = {'state': 'queued', 'expiry': None}
                self._order.append(job_id)

    def claim(self, worker, now, ttl):
        with self._lock:
            if ttl <= 0:
                return None

            # Find eligible jobs: queued or running whose expiry <= now
            # IDs chosen in insertion order
            for job_id in self._order:
                if job_id not in self.jobs:
                    continue
                job = self.jobs[job_id]

                # Check if job is eligible (queued or running) and expired
                if job['state'] in ('queued', 'running'):
                    expiry = job.get('expiry', 0)
                    if expiry <= now:
                        # Create new unique token for this claim
                        token = str(uuid4())
                        job['state'] = 'running'
                        job['worker'] = worker
                        job['token'] = token
                        job['expiry'] = now + ttl
                        return {'job_id': job_id, 'worker': worker, 'token': token}

            return None

    def renew(self, lease, now, ttl):
        with self._lock:
            if not isinstance(lease, dict) or 'token' not in lease or 'worker' not in lease:
                return False

            token = lease['token']
            worker = lease['worker']

            # Find the job matching this token and worker
            for job_id, job in self.jobs.items():
                if job.get('token') == token and job.get('worker') == worker:
                    # Check expiry > now (must not be already expired)
                    expiry = job.get('expiry', 0)
                    if expiry > now:
                        # Extend expiry
                        job['expiry'] = now + ttl
                        return True

            return False

    def complete(self, lease, now):
        with self._lock:
            if not isinstance(lease, dict) or 'token' not in lease or 'worker' not in lease:
                return False

            token = lease['token']
            worker = lease['worker']

            # Find the job matching this token and worker
            for job_id, job in self.jobs.items():
                if job.get('token') == token and job.get('worker') == worker:
                    # Check expiry > now (must not be already expired)
                    expiry = job.get('expiry', 0)
                    if expiry > now:
                        job['state'] = 'completed'
                        return True

            return False
